-- (가)
SELECT COUNT(*) FROM PRODUCT
 WHERE PRICE > ALL (SELECT PRICE FROM PRODUCT WHERE CATEGORY = '도서');

-- (나)
SELECT COUNT(*) FROM PRODUCT
 WHERE PRICE > ANY (SELECT PRICE FROM PRODUCT WHERE CATEGORY = '도서');

-- (다)
SELECT COUNT(*) FROM PRODUCT
 WHERE PRICE > ALL (SELECT PRICE FROM PRODUCT
                     WHERE CATEGORY = '도서' AND PRICE IS NOT NULL);

-- (가)
SELECT CPN_CD FROM CPN_A UNION     SELECT CPN_CD FROM CPN_B;
-- (나)
SELECT CPN_CD FROM CPN_A INTERSECT SELECT CPN_CD FROM CPN_B;
-- (다)
SELECT CPN_CD FROM CPN_A MINUS     SELECT CPN_CD FROM CPN_B;

SELECT CATEGORY, BRAND, SUM(AMT)
  FROM SALES
 GROUP BY CUBE(CATEGORY, BRAND);

-- (가)
SELECT COUNT(*) FROM (SELECT RANK() OVER (ORDER BY SALES DESC) AS RK FROM BEST)
 WHERE RK <= 3;

-- (나)
SELECT COUNT(*) FROM (SELECT DENSE_RANK() OVER (ORDER BY SALES DESC) AS RK FROM BEST)
 WHERE RK <= 3;

-- (다)
SELECT PROD_ID FROM BEST
 ORDER BY SALES DESC
 FETCH FIRST 2 ROWS WITH TIES;

-- (가)
SELECT COUNT(*) FROM PRODUCT
 WHERE REGEXP_LIKE(PROD_CD, '^[A-Z]{2}[0-9]{3}$');

-- (나)
SELECT COUNT(*) FROM PRODUCT
 WHERE REGEXP_LIKE(PROD_CD, '^[A-Z]{2}[0-9]{3}$', 'i');

