CREATE TABLE ORDERS (
  ORD_NO NUMBER PRIMARY KEY,
  MEM_NO NUMBER REFERENCES MEMBER(MEM_NO) ON DELETE CASCADE
);
CREATE TABLE ORDER_ITEM (
  ORD_NO NUMBER REFERENCES ORDERS(ORD_NO) ON DELETE CASCADE,
  SEQ    NUMBER
);
CREATE TABLE REVIEW (
  RV_ID  VARCHAR2(5) PRIMARY KEY,
  MEM_NO NUMBER REFERENCES MEMBER(MEM_NO)
);

